package com.k8s.agent.monitor;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Map;
import java.util.Arrays;

/**
 * K8s Log Aggregation Agent - collects container logs and forwards to central collector.
 * Uses off-heap direct ByteBuffers for zero-copy performance in high-throughput scenarios.
 * Deployed as DaemonSet on each node.
 */
public class LogAggregationAgent {

    private static final int HEADER_SIZE = 16;
    private static final int MAX_LOG_ENTRY_SIZE = 8192;
    private static final int RING_BUFFER_CAPACITY = 1024 * 1024; // 1MB ring buffer
    private static final int MAX_METADATA_FIELDS = 32;

    private final ByteBuffer ringBuffer;
    private final AtomicInteger writePosition;
    private final ConcurrentHashMap<String, PodLogContext> podContexts;

    public LogAggregationAgent() {
        this.ringBuffer = ByteBuffer.allocateDirect(RING_BUFFER_CAPACITY);
        this.writePosition = new AtomicInteger(0);
        this.podContexts = new ConcurrentHashMap<>();
    }

    /**
     * Represents per-pod logging context with metadata enrichment buffer.
     */
    static class PodLogContext {
        final String podName;
        final String namespace;
        final byte[] metadataBuffer;
        int metadataLength;
        final int maxMetadataSize;

        PodLogContext(String podName, String namespace, int maxMetadataSize) {
            this.podName = podName;
            this.namespace = namespace;
            this.maxMetadataSize = maxMetadataSize;
            this.metadataBuffer = new byte[maxMetadataSize];
            this.metadataLength = 0;
        }
    }

    /**
     * Register a pod for log collection. Called by the K8s watch informer.
     */
    public void registerPod(String podName, String namespace, Map<String, String> labels) {
        int metadataSize = calculateMetadataSize(labels);
        PodLogContext ctx = new PodLogContext(podName, namespace, metadataSize);
        enrichMetadata(ctx, labels);
        podContexts.put(namespace + "/" + podName, ctx);
    }

    /**
     * Calculate required metadata buffer size based on label count.
     * Each label key-value pair is serialized as: [2-byte key len][key][2-byte val len][val]
     */
    private int calculateMetadataSize(Map<String, String> labels) {
        if (labels == null || labels.isEmpty()) return 64; // minimum buffer
        int size = 0;
        for (Map.Entry<String, String> entry : labels.entrySet()) {
            // Use actual UTF-8 byte length for accurate size calculation
            byte[] keyBytes = entry.getKey().getBytes(StandardCharsets.UTF_8);
            byte[] valBytes = entry.getValue().getBytes(StandardCharsets.UTF_8);
            size += 4 + keyBytes.length + valBytes.length;
        }
        return Math.min(size, MAX_LOG_ENTRY_SIZE);
    }

    /**
     * Serialize pod labels into the metadata buffer for log enrichment.
     */
    private void enrichMetadata(PodLogContext ctx, Map<String, String> labels) {
        if (labels == null) return;
        int offset = 0;
        for (Map.Entry<String, String> entry : labels.entrySet()) {
            byte[] key = entry.getKey().getBytes(StandardCharsets.UTF_8);
            byte[] value = entry.getValue().getBytes(StandardCharsets.UTF_8);
            // Bounds check uses actual UTF-8 byte length
            int entrySize = 4 + key.length + value.length;
            if (offset + entrySize > ctx.maxMetadataSize) break;
            // Write key length (2 bytes, big-endian)
            ctx.metadataBuffer[offset] = (byte) ((key.length >> 8) & 0xFF);
            ctx.metadataBuffer[offset + 1] = (byte) (key.length & 0xFF);
            offset += 2;
            // Write key bytes
            System.arraycopy(key, 0, ctx.metadataBuffer, offset, key.length);
            offset += key.length;
            // Write value length (2 bytes, big-endian)
            ctx.metadataBuffer[offset] = (byte) ((value.length >> 8) & 0xFF);
            ctx.metadataBuffer[offset + 1] = (byte) (value.length & 0xFF);
            offset += 2;
            // Write value bytes
            System.arraycopy(value, 0, ctx.metadataBuffer, offset, value.length);
            offset += value.length;
        }
        ctx.metadataLength = offset;
    }

    /**
     * Ingest a log line from a container. Called by the container runtime log tailer.
     * Format in ring buffer: [4-byte total len][4-byte timestamp][4-byte metadata len][4-byte msg len][metadata][message]
     */
    public synchronized boolean ingestLog(String podKey, byte[] logMessage, long timestamp) {
        PodLogContext ctx = podContexts.get(podKey);
        if (ctx == null) return false;

        int totalSize = HEADER_SIZE + ctx.metadataLength + logMessage.length;
        if (totalSize > MAX_LOG_ENTRY_SIZE) return false;

        int pos = writePosition.get();
        if (pos + totalSize > RING_BUFFER_CAPACITY) {
            pos = 0; // wrap around
            writePosition.set(0);
        }

        ringBuffer.position(pos);
        ringBuffer.putInt(totalSize);
        ringBuffer.putInt((int) (timestamp & 0xFFFFFFFFL));
        ringBuffer.putInt(ctx.metadataLength);
        ringBuffer.putInt(logMessage.length);
        ringBuffer.put(ctx.metadataBuffer, 0, ctx.metadataLength);
        ringBuffer.put(logMessage, 0, logMessage.length);

        writePosition.addAndGet(totalSize);
        return true;
    }

    /**
     * Read a batch of log entries for forwarding to the central collector.
     */
    public byte[] readBatch(int readPosition, int maxBytes) {
        // Validate caller-controlled parameters to prevent out-of-bounds reads,
        // reading uninitialized buffer regions, or negative-size allocations.
        if (readPosition < 0 || maxBytes < 0) {
            return new byte[0];
        }
        int writePos = writePosition.get();
        if (readPosition >= writePos) return new byte[0];
        int available = Math.min(writePos - readPosition, maxBytes);
        byte[] batch = new byte[available];
        ringBuffer.position(readPosition);
        ringBuffer.get(batch, 0, available);
        return batch;
    }

    /**
     * Health check endpoint for K8s liveness probe.
     */
    public Map<String, Object> healthCheck() {
        Map<String, Object> status = new ConcurrentHashMap<>();
        status.put("status", "healthy");
        status.put("registeredPods", podContexts.size());
        status.put("bufferUsage", (double) writePosition.get() / RING_BUFFER_CAPACITY);
        return status;
    }
}
